function gridColor(value) {{
  // value in [0,1], center 0.5
  const d = Math.max(-0.15, Math.min(0.15, value - 0.5));
  const t = (d + 0.15) / 0.30; // 0..1
  // interpolate red -> neutral -> green
  const r0=[255,110,110], r1=[255,255,255], r2=[139,255,176];
  let c;
  if (t<0.5) {{
    const u=t/0.5;
    c=[r0[0]+(r1[0]-r0[0])*u, r0[1]+(r1[1]-r0[1])*u, r0[2]+(r1[2]-r0[2])*u];
  }} else {{
    const u=(t-0.5)/0.5;
    c=[r1[0]+(r2[0]-r1[0])*u, r1[1]+(r2[1]-r1[1])*u, r1[2]+(r2[2]-r1[2])*u];
  }}
  return `rgba(${c.map(x=>Math.round(x)).join(',')},0.18)`;
}}

function makeHeatmap(elId) {{
  const el=document.getElementById(elId);
  const rb=[...new Set(heatCells.map(d=>d.rating_bracket))];
  const tc=[...new Set(heatCells.map(d=>d.tc_bucket))];
  // stable ordering
  const tcOrder=['Bullet (<=3m)','Blitz (4-8m)','Rapid (9-14m)','Rapid+ (15-29m)','Classical (>=30m)'];
  tc.sort((a,b)=>tcOrder.indexOf(a)-tcOrder.indexOf(b));

  const table=document.createElement('table');
  const thead=document.createElement('thead');
  const trh=document.createElement('tr');
  trh.innerHTML = `<th></th>${tc.map(x=>`<th>${x.replace(' (','<br>(')}</th>`).join('')}`;
  thead.appendChild(trh);
  table.appendChild(thead);

  const map=new Map(heatCells.map(d=>[`${d.rating_bracket}||${d.tc_bucket}`, d]));
  const tbody=document.createElement('tbody');
  rb.forEach(r=>{{
    const tr=document.createElement('tr');
    tr.innerHTML = `<td><span class='tag'>${r}</span></td>` + tc.map(t=>{{
      const d=map.get(`${r}||${t}`);
      if(!d) return `<td class='small'>—</td>`;
      const v=d.white_win_rate_decisive;
      const bg=gridColor(v);
      const cls=v>=0.5?'pos':'neg';
      return `<td style='background:${bg}; border:1px solid rgba(255,255,255,.06); border-radius:10px;'><div class='${cls}' style='font-weight:800;'>${(v*100).toFixed(1)}%</div><div class='small'>n=${d.decisive_games}</div></td>`;
    }}).join('');
    tbody.appendChild(tr);
  }});
  table.appendChild(tbody);
  el.appendChild(table);
}}

