new Chart(document.getElementById('whiteByTc'), {{
  type: 'bar',
  data: {{
    labels: whiteByTc.filter(d=>d.tc_bucket!=='Unknown').map(d=>d.tc_bucket),
    datasets: [{{
      label: 'White win rate (decisive)',
      data: whiteByTc.filter(d=>d.tc_bucket!=='Unknown').map(d=>d.white_win_rate_decisive),
      backgroundColor: '#6ea8ff',
      borderColor: '#6ea8ff'
    }}]
  }},
