  th, td {{ padding: 9px 10px; border-bottom: 1px solid var(--border); vertical-align: top; }}
  th {{ text-align: left; color: var(--muted); font-weight: 650; }}
  tr:hover td {{ background: rgba(255,255,255,.02); }}
  .tag {{ display:inline-block; padding: 2px 8px; border-radius: 999px; border:1px solid var(--border); color: var(--muted); font-size: 12px; }}
  .pos {{ color: var(--accent2); font-weight: 650; }}
  .neg {{ color: var(--danger); font-weight: 650; }}
  .mono {{ font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace; }}
  .callout {{ border-left: 3px solid var(--accent); padding: 10px 12px; background: rgba(110,168,255,.07); border-radius: 10px; }}
  canvas {{ width:100% !important; height: 340px !important; }}
  .tight canvas {{ height: 280px !important; }}
  @media (max-width: 980px) {{
    .kpi {{ grid-column: span 6; }}
    .span6, .span7, .span5, .span8, .span4 {{ grid-column: span 12; }}
  }}
</style>
</head>
<body>
<div class="wrap">
  <h1>{title}</h1>
  <p class="sub">Data-driven analysis of <b>{total}</b> Lichess games (source: <span class="mono">benchmark/data.csv</span>). Focus areas: first-move advantage, rating differential effects, opening success, and time control dynamics.</p>

  <div class="grid">
    <div class="card kpi">
      <div class="label">Total games</div>
      <div class="value">{total}</div>
      <div class="note">Rated: {rated} ({rated_share}) • Unrated: {unrated} ({unrated_share})</div>
    </div>
    <div class="card kpi">
      <div class="label">White win rate (decisive)</div>
      <div class="value">{white_win_rate}</div>
      <div class="note">95% CI: {white_ci_low}–{white_ci_high} • Edge vs 50%: {white_edge_pp}</div>
    </div>
    <div class="card kpi">
      <div class="label">Checkmate rate</div>
      <div class="value">{checkmate_rate}</div>
      <div class="note">Mate: {mate} • Resign: {resign} • OOT: {oot} • Draw: {draw_status}</div>
    </div>
    <div class="card kpi">
      <div class="label">Average game length</div>
      <div class="value">{avg_plies} plies</div>
      <div class="note">Turns are half-moves (plies) per dataset schema.</div>
    </div>
  </div>

  <h2 id="overview">Dataset Overview &amp; Game Distribution</h2>
  <div class="grid">
    <div class="card span6">
      <h3>Winners</h3>
      <div class="tight"><canvas id="winnersChart"></canvas></div>
      <div class="small">Counts: White {w_white} • Black {w_black} • Draw {w_draw}</div>
    </div>
    <div class="card span6">
      <h3>Game end method (victory_status)</h3>
      <div class="tight"><canvas id="statusChart"></canvas></div>
      <div class="small">Most games end by resignation, followed by checkmate.</div>
    </div>
  </div>

  <h2 id="color">White vs. Black: The First-Move Advantage</h2>
  <div class="card callout">
    <b>Headline:</b> Across decisive games, White wins {white_win_rate} (95% CI {white_ci_low}–{white_ci_high}), a {white_edge_pp} edge over 50%.
    <div class="small" style="margin-top:6px">Draw-inclusive: White’s average score is {white_score_all} where win=1, draw=0.5, loss=0.</div>
  </div>

  <div class="grid" style="margin-top:12px">
    <div class="card span7">
      <h3>White win rate by time control bucket (decisive games)</h3>
      <canvas id="whiteByTc"></canvas>
      <div class="small">Bucket uses base minutes from <span class="mono">increment_code</span>.</div>
    </div>
    <div class="card span5">
      <h3>Centerpiece: rating × time control heatmap (decisive)</h3>
      <div class="small">Cells require ≥100 decisive games.</div>
      <div id="heatmap" style="margin-top:10px"></div>
      <div class="small" style="margin-top:10px">Largest observed White edge: <span class="tag">{best_rb}</span> × <span class="tag">{best_tc}</span> → {best_p} (n={best_n}).</div>
      <div class="small">Lowest observed White edge: <span class="tag">{worst_rb}</span> × <span class="tag">{worst_tc}</span> → {worst_p} (n={worst_n}).</div>
    </div>
  </div>

  <h2 id="rating">Rating Dynamics and Their Impact on Outcomes</h2>
  <div class="grid">
    <div class="card span8">
      <h3>Win expectation shifts with rating differential</h3>
      <canvas id="ratingDiff"></canvas>
      <div class="small">Bins are by <span class="mono">white_rating − black_rating</span>. Y-axis is White’s draw-inclusive score.</div>
    </div>
    <div class="card span4">
      <h3>Higher-rated win rate by |rating gap|</h3>
      <canvas id="higherRated"></canvas>
      <div class="small">Point-biserial r = {pointbiserial_r} (p≈{pointbiserial_p}) between |gap| and higher-rated win indicator.</div>
    </div>
  </div>

  <div class="grid">
    <div class="card span12">
      <h3>Average game length by victory status (plies)</h3>
      <canvas id="turnsByStatus"></canvas>
      <div class="small">Drawn games average {turns_draw} plies vs mates {turns_mate}.</div>
    </div>
  </div>

  <h2 id="opening">Opening Analysis: Popular Openings and Their Success Rates</h2>
  <div class="grid">
    <div class="card span7">
      <h3>Top openings by frequency (top 15)</h3>
      <canvas id="openingsChart"></canvas>
      <div class="small">Bar = games; line = White score (win=1, draw=0.5).</div>
    </div>
    <div class="card span5">
      <h3>Openings where Black outperforms (within top 15)</h3>
      <table>
        <thead><tr><th>Opening</th><th>Games</th><th>White score</th><th>White win (decisive)</th></tr></thead>
        <tbody>
          {black_rows}
        </tbody>
      </table>
      <div class="small" style="margin-top:8px">Empirical association; selection effects likely.</div>
    </div>
  </div>

  <div class="grid">
    <div class="card span12">
      <h3>Opening depth (opening_ply) vs outcomes</h3>
      <canvas id="openingPly"></canvas>
      <div class="small">Early deviations (lower <span class="mono">opening_ply</span>) coincide with higher mate rates in this dataset.</div>
    </div>
  </div>

  <h2 id="time">Time Control Patterns and Game Characteristics</h2>
  <div class="grid">
    <div class="card span6">
      <h3>Timeout share by time control bucket</h3>
      <canvas id="timeouts"></canvas>
    </div>
    <div class="card span6">
      <h3>Most common increment codes (top 12)</h3>
      <table>
        <thead><tr><th>Increment</th><th>Games</th><th>Avg plies</th><th>Mate</th><th>Resign</th><th>OOT</th><th>Draw</th></tr></thead>
        <tbody>
          {inc_rows}
        </tbody>
      </table>
    </div>
  </div>

  <h2 id="findings">Key Findings and Strategic Takeaways</h2>
  <div class="card">
    <ul style="margin: 0; padding-left: 18px;">
      <li><b>White has a measurable edge:</b> {white_win_rate} White wins in decisive games (95% CI {white_ci_low}–{white_ci_high}), i.e., {white_edge_pp} over 50%.</li>
      <li><b>Rating gaps dominate outcomes:</b> White’s expected score is {neg_score} when White is −200 to −150 Elo, versus {pos_score} when White is +150 to +200 Elo (draw-inclusive score).</li>
      <li><b>Color advantage is not uniform:</b> the rating×time heatmap ranges from near-even segments to {best_p} (e.g., {best_rb} × {best_tc}).</li>
      <li><b>Openings show large empirical spread:</b> within the top 15, several openings are sub-50% for White; the lowest is {worst_open_eco} {worst_open_name} at {worst_open_score} White score.</li>
      <li><b>Time pressure shifts termination modes:</b> timeouts are concentrated in faster controls; resignations still dominate across buckets.</li>
    </ul>
  </div>

  <div style="margin-top:24px; color: var(--muted); font-size: 12px;">
    Built from <span class="mono">benchmark/data.csv</span>. All figures computed from the dataset; no external priors.
  </div>
</div>
"""

js_block = r"""
<script>
const payload = __PAYLOAD__;

function gridColor(value) {
  const d = Math.max(-0.15, Math.min(0.15, value - 0.5));
  const t = (d + 0.15) / 0.30;
  const r0=[255,110,110], r1=[255,255,255], r2=[139,255,176];
  let c;
  if (t<0.5) {
    const u=t/0.5;
    c=[r0[0]+(r1[0]-r0[0])*u, r0[1]+(r1[1]-r0[1])*u, r0[2]+(r1[2]-r0[2])*u];
  } else {
    const u=(t-0.5)/0.5;
    c=[r1[0]+(r2[0]-r1[0])*u, r1[1]+(r2[1]-r1[1])*u, r1[2]+(r2[2]-r1[2])*u];
  }
  return `rgba(${Math.round(c[0])},${Math.round(c[1])},${Math.round(c[2])},0.18)`;
}

function makeHeatmap() {
  const heatCells = payload.heatCells;
  const el=document.getElementById('heatmap');
  const rb=[...new Set(heatCells.map(d=>d.rating_bracket))];
  const tc=[...new Set(heatCells.map(d=>d.tc_bucket))];
  const tcOrder=['Bullet (<=3m)','Blitz (4-8m)','Rapid (9-14m)','Rapid+ (15-29m)','Classical (>=30m)'];
  tc.sort((a,b)=>tcOrder.indexOf(a)-tcOrder.indexOf(b));

  const table=document.createElement('table');
  const thead=document.createElement('thead');
  const trh=document.createElement('tr');
  trh.innerHTML = `<th></th>${tc.map(x=>`<th>${x.replace(' (','<br>(')}</th>`).join('')}`;
  thead.appendChild(trh);
  table.appendChild(thead);

  const map=new Map(heatCells.map(d=>[`${d.rating_bracket}||${d.tc_bucket}`, d]));
  const tbody=document.createElement('tbody');
  rb.forEach(r=>{
    const tr=document.createElement('tr');
    tr.innerHTML = `<td><span class='tag'>${r}</span></td>` + tc.map(t=>{
      const d=map.get(`${r}||${t}`);
      if(!d) return `<td class='small'>—</td>`;
      const v=d.white_win_rate_decisive;
      const bg=gridColor(v);
      const cls=v>=0.5?'pos':'neg';
      return `<td style='background:${bg}; border:1px solid rgba(255,255,255,.06); border-radius:10px;'><div class='${cls}' style='font-weight:800;'>${(v*100).toFixed(1)}%</div><div class='small'>n=${d.decisive_games}</div></td>`;
    }).join('');
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  el.appendChild(table);
}

const chartDefaults = {
  responsive: true,
  maintainAspectRatio: false,
  plugins: {
    legend: { labels: { color: '#c7d2f0' } },
    tooltip: { mode:'index', intersect:false }
  },
  scales: {
    x: { ticks: { color:'#c7d2f0' }, grid: { color: 'rgba(255,255,255,.06)' } },
    y: { ticks: { color:'#c7d2f0' }, grid: { color: 'rgba(255,255,255,.06)' } }
  }
};

new Chart(document.getElementById('winnersChart'), {
  type: 'doughnut',
  data: { labels: payload.winners.map(d=>d.label), datasets: [{ data: payload.winners.map(d=>d.value), backgroundColor:['#6ea8ff','#ff6e6e','#ffcc66'] }] },
  options: { ...chartDefaults, plugins: { ...chartDefaults.plugins, legend: { position:'bottom', labels: { color:'#c7d2f0' } } } }
});

new Chart(document.getElementById('statusChart'), {
  type: 'doughnut',
  data: { labels: payload.status.map(d=>d.label), datasets: [{ data: payload.status.map(d=>d.value), backgroundColor:['#8bffb0','#6ea8ff','#ff6e6e','#ffcc66'] }] },
  options: { ...chartDefaults, plugins: { ...chartDefaults.plugins, legend: { position:'bottom', labels: { color:'#c7d2f0' } } } }
});

const tc = payload.whiteByTc.filter(d=>d.tc_bucket!=='Unknown');
new Chart(document.getElementById('whiteByTc'), {
  type: 'bar',
  data: { labels: tc.map(d=>d.tc_bucket), datasets: [{ label:'White win rate (decisive)', data: tc.map(d=>d.white_win_rate_decisive), backgroundColor:'#6ea8ff' }] },
  options: { ...chartDefaults, scales: { x: chartDefaults.scales.x, y: { ...chartDefaults.scales.y, min:0.42, max:0.58, ticks: { color:'#c7d2f0', callback:(v)=> (v*100).toFixed(0)+'%' } } } }
});

new Chart(document.getElementById('ratingDiff'), {
  type: 'line',
  data: { labels: payload.signedBins.map(d=>d.rating_diff_bin), datasets: [{ label:'White score (win=1, draw=0.5)', data: payload.signedBins.map(d=>d.white_score), borderColor:'#8bffb0', backgroundColor:'rgba(139,255,176,.12)', pointRadius:3, tension:0.25, fill:true }] },
  options: { ...chartDefaults, scales: { x: { ...chartDefaults.scales.x, ticks: { color:'#c7d2f0', maxRotation: 90, minRotation: 60 } }, y: { ...chartDefaults.scales.y, min:0.1, max:0.9, ticks: { color:'#c7d2f0', callback:(v)=> (v*100).toFixed(0)+'%' } } } }
});

new Chart(document.getElementById('higherRated'), {
  type: 'bar',
  data: { labels: payload.absBins.map(d=>d.abs_rating_diff_bin), datasets: [{ label:'Higher-rated win rate', data: payload.absBins.map(d=>d.higher_rated_win_rate), backgroundColor:'#ffcc66' }] },
  options: { ...chartDefaults, scales: { x: { ...chartDefaults.scales.x, ticks: { color:'#c7d2f0', maxRotation: 80, minRotation: 50 } }, y: { ...chartDefaults.scales.y, min:0.35, max:0.95, ticks: { color:'#c7d2f0', callback:(v)=> (v*100).toFixed(0)+'%' } } } }
});

new Chart(document.getElementById('turnsByStatus'), {
  type: 'bar',
  data: { labels: payload.turnsByStatus.map(d=>d.status), datasets: [{ label:'Average plies', data: payload.turnsByStatus.map(d=>d.mean), backgroundColor:'#6ea8ff' }] },
  options: { ...chartDefaults }
});

new Chart(document.getElementById('openingsChart'), {
  data: {
    labels: payload.openings.map(o=>`${o.opening_eco} ${o.opening_name}`),
    datasets: [
      { type:'bar', label:'Games', yAxisID:'y', data: payload.openings.map(o=>o.games), backgroundColor:'rgba(110,168,255,.45)', borderColor:'#6ea8ff' },
      { type:'line', label:'White score', yAxisID:'y1', data: payload.openings.map(o=>o.white_score), borderColor:'#8bffb0', backgroundColor:'rgba(139,255,176,.12)', pointRadius:3, tension:0.25 }
    ]
  },
  options: { ...chartDefaults, scales: { x: { ...chartDefaults.scales.x, ticks: { color:'#c7d2f0', maxRotation: 85, minRotation: 60 } }, y: { ...chartDefaults.scales.y, position:'left' }, y1: { ...chartDefaults.scales.y, position:'right', min:0.3, max:0.7, grid: { drawOnChartArea:false }, ticks: { color:'#c7d2f0', callback:(v)=> (v*100).toFixed(0)+'%' } } } }
});

new Chart(document.getElementById('openingPly'), {
  data: {
    labels: payload.opPlyBins.map(d=>d.opening_ply_bin),
    datasets: [
      { type:'line', label:'Avg plies', yAxisID:'y', data: payload.opPlyBins.map(d=>d.avg_turns), borderColor:'#6ea8ff', pointRadius:3, tension:0.25 },
      { type:'bar', label:'Mate rate', yAxisID:'y1', data: payload.opPlyBins.map(d=>d.mate_rate), backgroundColor:'rgba(139,255,176,.35)' },
      { type:'bar', label:'Resign rate', yAxisID:'y1', data: payload.opPlyBins.map(d=>d.resign_rate), backgroundColor:'rgba(255,204,102,.30)' },
      { type:'bar', label:'OOT rate', yAxisID:'y1', data: payload.opPlyBins.map(d=>d.outoftime_rate), backgroundColor:'rgba(255,110,110,.30)' }
    ]
  },
  options: { ...chartDefaults, scales: { x: chartDefaults.scales.x, y: { ...chartDefaults.scales.y, position:'left' }, y1: { ...chartDefaults.scales.y, position:'right', min:0, max:0.75, grid: { drawOnChartArea:false }, ticks: { color:'#c7d2f0', callback:(v)=> (v*100).toFixed(0)+'%' } } } }
});

const oot = {};
for (const r of payload.tcShares) { if (r.victory_status==='outoftime') oot[r.tc_bucket]=r.share; }
const tcOrder=['Bullet (<=3m)','Blitz (4-8m)','Rapid (9-14m)','Rapid+ (15-29m)','Classical (>=30m)'];
new Chart(document.getElementById('timeouts'), {
  type: 'bar',
  data: { labels: tcOrder, datasets: [{ label:'Out-of-time share', data: tcOrder.map(k=>oot[k]||0), backgroundColor:'#ff6e6e' }] },
  options: { ...chartDefaults, scales: { x: chartDefaults.scales.x, y: { ...chartDefaults.scales.y, min:0, max:0.20, ticks: { color:'#c7d2f0', callback:(v)=> (v*100).toFixed(0)+'%' } } } }
});

makeHeatmap();
</script>
</body>
</html>
"""

html = head.format(**ctx, black_rows=black_rows, inc_rows=inc_rows)
html += js_block.replace('__PAYLOAD__', json.dumps(js_payload, ensure_ascii=False))

Path('output').mkdir(exist_ok=True)
Path('output/final_report.html').write_text(html, encoding='utf-8')
print('Wrote output/final_report.html')
PY"}
